  const s = _meSwings.get(cl) || null;
  const hands = _meHands(s);
  const rs = s ? s.rounds.filter(r => !hands || r.verbs.includes(hands.mh)) : [];
  const fit = rs.length >= 5 ? _meSwingFit(rs) : null;
  const period = fit ? fit.period : null;
