  var now = (d.now || Date.now()) / 1000, t0 = now - 600, pw = W - L - R;
  var X = function (t) { return L + Math.max(0, Math.min(1, (t - t0) / 600)) * pw; };
  var rs = (d.series && d.series.router) || [], gs = (d.series && d.series.game) || [];
