        type: 'text_overlay',
        text: String(t.overlay_text || t.name || 'TRIGGER').slice(0, 200),
        color: String(t.overlay_color || 'red').slice(0, 20),
        duration_ms: Math.max(500, Math.min(60000, parseInt(t.overlay_ms, 10) || 5000)),
