    name:          tpl.label,
    pattern:       tpl.pattern || '',
    pattern_flags: 'i',
    use_regex:     true,
    enabled:       true,
    cooldown_seconds:  tpl.cooldown_seconds || 0,
    timer_duration_sec: 0,
    end_early_pattern:  null,
    end_use_regex:      true,
