  if (!prev || !prev.target_name || !next.target_name) return;
  const pn = String(prev.target_name).replace(/^#/, '').trim();
  const nn = String(next.target_name).replace(/^#/, '').trim();
  const base = nn.replace(/[`'’]s\s+corpse\d*$/i, '');
