function _replayDeathsLive() {
  const st = _replayState;
  if (st && (st.running || (st.tailUntil && Date.now() < st.tailUntil))) return true;
  if (_replayMobDeaths.length) _replayMobDeaths.length = 0;
  return false;
}
// The replay's log time right now. During the walk it moves through st.clk, a segment from the previous played
// line's time to the next one's across the wait the worker sleeps: real pace is 1x while the gap is under
// REPLAY_MAX_GAP_MS and faster across a compressed lull; fast pace holds still on the last line (rate 0) and
// jumps when the next plays. After the walk (done or stopped) it runs 1x through the tail. `untilMs` bounds the
// page's extrapolation so a poll never overshoots a segment.
function _replayClockForWeb() {
  if (!_replayDeathsLive()) return null;
  const st = _replayState, wall = Date.now();
  if (!st.running) {
    return { nowMs: st.tailFromMs + (wall - st.tailWall), rate: 1, untilMs: null, pace: st.pace || 'real', tail: true };
  }
  const c = st.clk || { fromMs: st.fromMs, toMs: st.fromMs, wallStart: wall, wallMs: 0 };
  if (!(c.wallMs > 0)) return { nowMs: c.toMs, rate: 0, untilMs: c.toMs, pace: st.pace || 'real', tail: false };
  const f = Math.max(0, Math.min(1, (wall - c.wallStart) / c.wallMs));
  return { nowMs: c.fromMs + (c.toMs - c.fromMs) * f, rate: (c.toMs - c.fromMs) / c.wallMs, untilMs: c.toMs,
           pace: st.pace || 'real', tail: false };
}
function _replayDeathsSnapshot() {
  const clock = _replayClockForWeb();
  if (!clock) return null;
  const cut = clock.nowMs - RECENT_DEATHS_SHOW_MS;
  return _replayMobDeaths.filter(e => e.atMs >= cut).map(e => ({ name: e.name, zone: e.zone, atMs: e.atMs, boss: e.boss, replay: true }));
}
function _cancelTimersOnMobDeath(line) {
  const dead = _deadMobNameFromLine(line);
  if (!dead) return 0;
  const deadLower = dead.toLowerCase();
  if (deadLower === 'you') return 0;   // "You died." — never a timer target
  let cancelled = 0;
  for (const [id, row] of _activeTimers) {
    const tgt = row.target ? String(row.target).toLowerCase() : null;
    if (tgt && tgt === deadLower) { _activeTimers.delete(id); cancelled++; }
  }
  if (cancelled) console.log('[timers] ' + dead + ' died — cleared ' + cancelled + ' countdown' + (cancelled === 1 ? '' : 's'));
  return cancelled;
}

// A mob died: its debuff countdowns (the "<mob> - <spell>" rows _builtinTimerRows builds from _buffLandingsByTarget)
// go with it (the guild lead, 2026-10-19: "when a mob dies it should remove those triggers for debuffs"). Deleted from
// the map, so the very next snapshot omits the rows and the overlay drops them instead of sitting at 00:00.
// The map is keyed by NAME, so two same-name mobs share one bucket and the only proof of WHICH mob an entry sits on
// is its target_id (null when unprovable, which is most landings). The rule, in order:
//   • the dead name is a player, a pet or an active charm → nothing (buffs on players and charm pets are never touched);
//   • the death carries a spawn id → drop the entries stamped with THAT id; entries with no id go too, but only while
//     the bucket is provably one mob (no entry stamped with another id, and the name is not seen at K>=2);
//   • the death has no id → drop only when the bucket is provably one mob (at most one distinct id, K<2). With two
//     or more same-name mobs and no id we cannot say whose timers are whose, so nothing is removed — they expire.
// Charm spells and friendly buffs stay (a beneficial spell is not a debuff; Pacify/Harmony count as ours to clear).
function _dropDebuffTimersOnDeath(deadName, spawnId, atMs, src) {
  if (!deadName) return 0;
  const lower = String(deadName).trim().toLowerCase();
  if (!lower || lower === 'you') return 0;
  if (whoData.has(lower) || _petOwnerByName(lower)) return 0;
  if (_watchedCharacters().some(c => String(c).toLowerCase() === lower)) return 0;
  const mp = _buffLandingsByTarget.get(lower);
  if (!mp || !mp.size) return 0;
  const nowMs = Date.now();
  const id = Number(spawnId) > 0 ? Number(spawnId) : null;
  const at = Number.isFinite(atMs) ? atMs : nowMs;
  const cand = [];
  for (const [k, b] of mp) {
    if (!b || b.is_charm_spell || CHARM_SPELLS.has(String(b.name || '').toLowerCase())) continue;
    if (_spellGood(b.name) === 1 && !_isPacifySpell(b.name)) continue;
    if ((Number(b.landed_at) || 0) > at + 1500) continue;   // landed after the death: a new mob of the same name
    cand.push(k);
  }
  const ids = new Set();
  for (const k of cand) { const i = Number(mp.get(k).target_id); if (i > 0) ids.add(i); }
  const several = (typeof _mobTrackK === 'function' ? _mobTrackK(lower, nowMs) : 0) >= 2;
  let drop;
  if (id != null) {
    const other = [...ids].some(i => i !== id);
    drop = cand.filter(k => { const i = Number(mp.get(k).target_id); return i > 0 ? i === id : (!other && !several); });
  } else {
    drop = (ids.size <= 1 && !several) ? cand : [];
  }
  for (const k of drop) mp.delete(k);
  if (mp.size === 0) _buffLandingsByTarget.delete(lower);
  if (drop.length) {
    _savePetStateSoon();
    console.log('[timers] ' + deadName + (id ? ' #' + id : '') + ' died (' + (src || 'log') + ') — cleared ' + drop.length + ' debuff timer' + (drop.length === 1 ? '' : 's'));
  }
  return drop.length;
}

// ── #142 boss spawn-chain + tank-buster detection ───────────────────────────
// Data-driven, per-boss, reusable (#36). A "chain" encodes: when the PRECURSOR
// mob dies, the BOSS spawns spawn_delay_sec later and busts the tank at spawn,
// then re-busts on its own cadence. ALL THREE signals are pure LOG lines every
// raider parses locally — no Zeal, no cross-client relay (EQLogParser-style),
// so it works for everyone regardless of who's running Zeal.
//
// Grounded facts (eqemu_spells + guild lead, #142):
//   • Rage of Ssraeshza = spell 2310: SPA 11 base 10 (−90% attack speed) +
//     SPA 79 base −4000 (a ~4000 non-melee HIT). 0s cast, NO cast/land chat —
//     so it's undetectable by text regex; the 4000 non-melee DAMAGE line is the
//     signal (EQLogParser attributes the amount to the spell; so do we).
//   • Fight: "Blood of Ssraeshza" dies → the Emperor's spawn buster lands 2:10
//     later (a Paladin DAs it), then it re-busts every ~60s.
// The spawn countdown is the pre-warn a Paladin needs to DA the spawn bust: it
// runs the full cycle and its warning is the actual "DA NOW" cue.
//
// The guild lead 2026-07-31: spawn cycle 2m10s, call DA at 2:00. So spawn_delay_sec is
// the CYCLE (130s) and spawn_warn_sec the LEAD (10s) → "Paladin DA NOW" fires
// at t+120s, 10s before the bust. Previously the cycle was modelled as 120s,
// which put the callout at t+110s — a 20s lead that outran an 18s Divine Aura.
// Do NOT "fix" this by shortening the cycle: the countdown row's zero must land
// on the bust, and the warn offset is the only knob for the callout.
const BOSS_SPAWN_CHAINS = [
  {
    precursor:         'Blood of Ssraeshza',       // its death arms the spawn pre-warn
    boss:              'Emperor Ssraeshza',         // spawn buster lands spawn_delay_sec after that
    spawn_delay_sec:   130,                         // 2:10 full cycle (the guild lead, 2026-07-31)
    spawn_label:       'Emperor spawn + buster',
    spawn_warn_sec:    10,                          // → "DA NOW" at 2:00, 10s before the bust
    spawn_warn_text:   'Paladin DA NOW',
    spawn_fire_text:   'Emperor spawn buster in 2:10 — Paladin ready to DA',
    buster_damage:     4000,                        // Rage of Ssraeshza DD (spell 2310), raw/unmitigated
    buster_damage_tol: 1200,                        // size window — INFERRED (unattributed) path ONLY
    buster_min_floor:  500,                         // ATTRIBUTED path: any Emperor non-melee ≥ this = buster (skips DoT/DS ticks; mitigation-proof)
    buster_cadence_sec: 60,                         // re-bust cadence (guild lead)
    buster_label:      'Tank Buster',
    buster_warn_sec:   10,
    buster_warn_text:  'TANK BUSTER incoming',
    buster_fire_text:  'TANK BUSTER',
  },
];
// Per-boss last-buster wall-clock so a single cast (seen once per observer, but
// possibly echoed across a box's logs) can't machine-gun the re-arm.
const _busterLastFire = new Map();

// Arm (or RE-ARM) a boss countdown and optionally fire a callout NOW. Local
// only — every raider detects the driving log line independently, so no relay.
// A re-fire of the same (boss,label) RESETS the same row in place because the
// synthetic trigger id is stable (DnDOverlay convention, via _startTimer).
// target=boss so _cancelTimersOnMobDeath clears it the instant the boss dies.
function _armBossCountdown(opts) {
  const now = opts.tsMs || Date.now();
  if (opts.fireText) {
    _pushOverlay({
      text:    opts.fireText,
      tts:     opts.fireText,
      trigger: (opts.label || 'timer') + ' — ' + opts.boss,
      scope:   'guild',
      rule_key: 'builtin:timer_callout',
      firedAt: now,
      test:    false,
    });
  }
  _startTimer({
    id:                 'boss-chain|' + opts.boss + '|' + opts.label,
    name:               opts.label,
    timer_duration_sec: opts.durationSec,
    warning_seconds:    opts.warnSec || 0,
    warning_text:       opts.warnText || null,
    actions:            [{ color: opts.color || 'red' }],
    _scope:             'guild',
    _ruleKey:           'builtin:timer_callout',
  }, now, false, { target: opts.boss });
}

// Precursor death → arm the boss spawn pre-warn countdown. Runs off the same
// slain/death lines _cancelTimersOnMobDeath reads.
function _checkBossSpawnChain(line, tsMs) {
  const dead = _deadMobNameFromLine(line);
  if (!dead) return;
  const deadLower = dead.toLowerCase();
  for (const c of BOSS_SPAWN_CHAINS) {
    if (deadLower !== c.precursor.toLowerCase()) continue;
    _armBossCountdown({
      boss: c.boss, label: c.spawn_label, durationSec: c.spawn_delay_sec,
      warnSec: c.spawn_warn_sec, warnText: c.spawn_warn_text,
      fireText: c.spawn_fire_text, color: 'gold', tsMs,
    });
    console.log('[boss-chain] ' + c.precursor + ' died — ' + c.boss + ' spawns in ' + c.spawn_delay_sec + 's');
  }
}

// Tank-buster damage line → fire "TANK BUSTER" + (re)arm the cadence countdown.
// Reuses parseEvent's attacker/amount (does NOT reinvent the line format); the
// non-melee marker is read off the raw line so a same-size MELEE swing can't
// false-fire.
//
// Two detection paths with DIFFERENT amount gates. The live log is the
// ATTRIBUTED form — "Emperor Ssraeshza hit <player> for N points of non-melee
// damage" (screenshot, madman_003 2026-07-22):
//   • ATTRIBUTED (attacker == boss): the buster is the Emperor's ONLY non-melee
//     output, so a named non-melee hit from him IS Rage of Ssraeshza REGARDLESS
//     of size. We deliberately DON'T gate on ~4000 here — rune + spell-shield
//     mitigation on the MT drops the visible number well below the raw 4000, and
//     a size gate would silence the callout exactly when the tank IS getting hit
//     (the guild lead, 2026-07-22). Only a small floor to skip DoT/DS ticks.
//   • INFERRED (no attacker, this boss is the active fight, EQLogParser-style):
//     can't attribute, so KEEP the ~4000±tol size signature to tell the buster
//     from other anonymous non-melee (DS procs, dirges).
function _checkTankBuster(ev, line, tsMs) {
  if (!ev || ev.type !== 'damage' || !(ev.amount > 0)) return;
  if (!/non-melee/i.test(line)) return;   // the buster is a spell hit, not melee
  const attackerLower = ev.attacker ? String(ev.attacker).toLowerCase() : null;
  const curBoss = (stats.currentEncounterThreat && stats.currentEncounterThreat.bossName)
    ? String(stats.currentEncounterThreat.bossName).toLowerCase() : null;
  for (const c of BOSS_SPAWN_CHAINS) {
    const bossLower = c.boss.toLowerCase();
    const attributed = attackerLower === bossLower;
    const inferred   = !attackerLower && curBoss === bossLower;
    if (!attributed && !inferred) continue;
    // Amount gate depends on the path (see header comment): attributed fires at
    // any size above a floor (mitigation-proof); inferred needs the size match.
    if (attributed) {
      if (ev.amount < (c.buster_min_floor || 500)) continue;
    } else if (Math.abs(ev.amount - c.buster_damage) > c.buster_damage_tol) {
      continue;
    }
    const key = 'buster|' + bossLower;
    if ((tsMs || Date.now()) - (_busterLastFire.get(key) || 0) < 8000) return;   // dupe/echo guard
    _busterLastFire.set(key, tsMs || Date.now());
    _armBossCountdown({
      boss: c.boss, label: c.buster_label, durationSec: c.buster_cadence_sec,
      warnSec: c.buster_warn_sec, warnText: c.buster_warn_text,
      fireText: c.buster_fire_text, color: 'red', tsMs,
    });
    console.log('[boss-chain] tank buster landed on ' + c.boss + ' — re-armed ' + c.buster_cadence_sec + 's countdown');
    return;
  }
}

// ── #36 AoE-dance callouts (OUT / IN + countdown) ────────────────────────────
// Data-driven melee-dance helper, REUSING the #142 countdown machinery
// (_armBossCountdown → _startTimer, buster-style effect detection). For a boss
// whose PBAE forces the melee off the mob ("run OUT before it hits, back IN
// after it lands"), we give the raid the exact tank-buster UX with different
// texts: (a) a pre-warn before the next AE, (b) a confirming IN callout the
// instant it lands, (c) an on-screen countdown to the next AE that re-syncs on
// every observed cast. The OUT/IN wording is PER ENTRY (out_text / in_text) —
// "MELEE OUT/IN" for a true PBAE where only the melee pile has to move.
//
// GROUNDED SIGNATURE — Dragon Roar, eqemu_spells 789 / 981 (identical rows),
// the fear PBAE on Vyzh`dra the Cursed (npc_types 162042).
// RE-SIGNATURED 2026-07-31. The original entry watched /flesh begins to
// liquefy\./i with burst_n 3 and never once fired — two independent reasons:
//   (1) wrong AE. That text is Caustic Mist 2814 / Putrefy Flesh 1956, and the
//       guild already owns it with a plain "Putrefy Flesh" trigger.
//   (2) burst_n 3 wanted three DISTINCT victims' land lines inside one log.
//       A raider's own log is dominated by the self-form, so the threshold was
//       effectively unreachable even on the right spell.
// The AE that actually lands on the raid is Dragon Roar (field-observed
// 2026-07-30/31). Two plain guild triggers already CALL the hit ("Dragon Roar"
// on the land line, "Dragon Roar (Resist)" on the resist) but NEITHER carries a
// timer_duration_sec — so raiders hear "it hit" and get no countdown to the
// NEXT one. THIS entry is that countdown; the plain triggers stay as the hit
// callout.
//   • cast_time 0 → no cast message; effect-detection only, exactly like the
//     #142 buster and the Vulak`Aerr entry below.
//   • cast_on_other is NULL → bystanders see NOTHING. The only evidence is your
//     OWN line, so burst_n is 1 — one self-line = the AE fired (burst_window_ms
//     still absorbs alt-log echoes). Same reasoning as Ancient Breath below.
//   • the two self-forms, and why BOTH are in the signature:
//       land   — "You lose control of yourself!"      (the fear taking hold)
//       resist — "You resist the Dragon Roar spell!"  (a resist still PROVES
//                the AE fired, and it is the ONLY line a resister ever gets —
//                without it, everyone who resisted would lose the countdown)
//     Neither line is the spell's catalog cast_on_you ("You flee in terror.");
//     both are the client/server fear + resist messages the guild's own live
//     triggers already match, i.e. field truth beats the catalog string here.
//   • cadence: spell recast_time 36000ms → 36s DEFAULT, FIELD-TUNABLE.
//     ⚠ Not catalog-confirmable for THIS npc: npc_spells_id 197 lists only
//     Mass Insanity 2813 + Caustic Mist 2814, and Dragon Roar appears in NO
//     Ssraeshza Temple spell list — Quarm scripts it outside npc_spells, so
//     there is no per-npc recast_delay override to read and 36s is the spell's
//     own cooldown. NPC AI doesn't cast strictly on cooldown anyway; like the
//     buster, the countdown RE-SYNCS on every AE observed, so an approximate
//     cadence is still useful. Confirm the real interval on the next kill.
//   • wording is the guild lead's call (the guild lead, stated twice): MELEE OUT /
//     MELEE IN — it's a PBAE, so casters at range never have to move.
const AOE_DANCE = [
  {
    boss:            'Vyzh`dra the Cursed',
    spell:           'Dragon Roar',                   // eqemu_spells 789/981 — fear PBAE (targettype 4), MR-based
    signature:       [/You lose control of yourself!/i,       // self-land (the fear)
                      /You resist the Dragon Roar spell!/i],  // resist — still proves the AE fired
    burst_n:         1,                               // self-only evidence (cast_on_other NULL) — see note above
    burst_window_ms: 2000,                            // echo/alt-log dupe absorber
    cadence_sec:     36,                              // FIELD-TUNABLE — spell recast_time 36000ms; confirm on next kill
    out_warn_sec:    5,                               // speak "MELEE OUT" this many seconds before the next AE
    out_text:        'MELEE OUT — Dragon Roar soon',  // countdown warning callout (the pre-warn)
    in_text:         'MELEE IN',                      // fired NOW when the AE lands (safe to re-engage)
    color:           'gold',
  },
  {
    // #182 — GROUNDED SIGNATURE — Ancient Breath, eqemu_spells 1486, on Vulak`Aerr
    // (npc_types 124128 "#Vulak`Aerr", npc_spells_id 1204, entry recast_delay -1):
    //   • cast_time 0 → no cast message; effect-detection only (like Caustic Mist).
    //   • cast_on_other is NULL → bystanders see NOTHING. The ONLY evidence is your
    //     own land line, so burst_n is 1 — one self-land = the AE fired (the
    //     burst_window_ms quiet window still absorbs alt-log echoes).
    //   • land-on-self: "Your life force drains away." (shared only with the Life
    //     Curse / Dark Siphon lifetaps + unused placeholders — the active-boss gate
    //     scopes it to this fight; a stray tap just re-syncs the countdown early).
    //   • cadence: spell recast_time 60000ms, npc entry defers (-1) → 60s default,
    //     FIELD-TUNABLE; re-syncs on every land you eat.
    //   • out_warn_sec 4 per the guild lead 2026-07-24: "calling DPS OUT at 4 seconds
    //     beforehand".
    boss:            'Vulak`Aerr',
    spell:           'Ancient Breath',                // eqemu_spells 1486 — PBAE (targettype 4), disease -150
    signature:       [/Your life force drains away\./i], // land-on-self ONLY (cast_on_other NULL)
    burst_n:         1,                               // one self-land = the AE fired (see note above)
    burst_window_ms: 2000,                            // echo/alt-log dupe absorber
    cadence_sec:     60,                              // FIELD-TUNABLE — spell recast_time 60000ms
    out_warn_sec:    4,                               // speak "DPS OUT" 4s before the predicted next AE
    out_text:        'DPS OUT — Ancient Breath soon',
    in_text:         'DPS IN',
    color:           'gold',
  },
];
// One burst = one fire. Keyed per boss so a whole burst of land lines (and any
// cross-log echo) collapses to a single fire — the #36 analogue of _busterLastFire.
const _aoeDanceLastFire = new Map();   // boss(lc) → wall-clock ms of the last fire
const _aoeDanceBurst    = new Map();   // boss(lc) → { count, windowStartMs } rolling collector

// A signature land line → count it toward the active burst; once >= burst_n
// land within burst_window_ms, treat the AE as fired: push the entry's in_text
// ("MELEE IN"/"DPS IN") NOW and (re)arm the countdown to the NEXT AE (target =
// boss so death clears it, like the buster) whose warning at out_warn_sec
// speaks the entry's out_text pre-warn.
// GATED on the boss being the ACTIVE encounter (curBoss, same pattern as
// _checkTankBuster) so an identically-worded land line on trash elsewhere can't
// fire it. Local only — every raider's own log carries the land burst.
function _checkAoeDance(line, tsMs) {
  if (!line) return;
  const curBoss = (stats.currentEncounterThreat && stats.currentEncounterThreat.bossName)
    ? String(stats.currentEncounterThreat.bossName).toLowerCase() : null;
  if (!curBoss) return;                                       // no active fight → never fire
  const now = tsMs || Date.now();
  for (const d of AOE_DANCE) {
    if (curBoss !== d.boss.toLowerCase()) continue;           // only THIS dance boss, and only while it's active
    if (!d.signature.some(rx => rx.test(line))) continue;     // not this AE's land text
    const key = d.boss.toLowerCase();
    // Post-fire quiet window: once we've fired for a burst, ignore the rest of
    // the same burst's land lines (and cross-log echoes) for burst_window_ms —
    // "one burst = one fire across the burst window" (echo guard).
    if (now - (_aoeDanceLastFire.get(key) || 0) < d.burst_window_ms) return;
    // Roll a fresh window if the previous collector is stale (>burst_window_ms
    // old), else accumulate this victim into it.
    let b = _aoeDanceBurst.get(key);
    if (!b || (now - b.windowStartMs) > d.burst_window_ms) {
      b = { count: 0, windowStartMs: now };
      _aoeDanceBurst.set(key, b);
    }
    b.count++;
    if (b.count < d.burst_n) return;                          // not a burst yet — a single stray line never fires
    // Burst confirmed — the AE just went off.
    _aoeDanceLastFire.set(key, now);
    _aoeDanceBurst.delete(key);
    _armBossCountdown({
      boss: d.boss, label: d.spell, durationSec: d.cadence_sec,
      warnSec: d.out_warn_sec, warnText: d.out_text,
      fireText: d.in_text, color: d.color || 'gold', tsMs: now,
    });
    console.log('[aoe-dance] ' + d.spell + ' on ' + d.boss + ' — ' + d.in_text + ' + re-armed ' + d.cadence_sec + 's countdown');
    return;
  }
}
// ── #207 callout dismissals — the implicit signal ───────────────────────────
// The guild lead 2026-08-03: "those lines should be dismissable AND we should track when
// things are dismissed so we learn from items that people either don't care
// about or may be inaccurate" (docs/DESIGN-callout-overlay.md §3.2).
//
// Two directions ride the EXISTING trigger_timing_feedback stream rather than a
// new table:
//   • `dismissed` — the raider cleared the row. The most honest signal we can
//     collect, and it costs them nothing extra: they were already swatting it
//     away. Compare the explicit thumbs-up widget — 47 votes from 7 people in a
//     month, because pressing a feedback button mid-raid competes with playing.
//   • `expired`   — the row aged out untouched. This is the CONTROL GROUP, and
//     it is what makes the signal readable at all: 3 dismissals is damning at 3
//     fires and meaningless at 300 (design §Gap C). Without it a dismissal
//     COUNT is not a dismissal RATE.
// Latency needs no column — `voted_at − fired_at` on a dismissed row already
// separates "swatted it instantly, it's noise" (<1s) from "read it, acted, then
// cleared it" (several seconds). Those are opposite verdicts.
//
// Scope, per docs/DESIGN-trigger-overlay-v2.md: per-user and session-scoped BY
// CONSTRUCTION. A dismissal clears the row in this agent only — it never
// relays, never touches guild_triggers, and dies with the process. One raider
// clearing a Death Touch bar must never clear the raid's.
//
// Votes are BATCHED (30s / 25 rows) into one upload: `expired` fires once per
// countdown per raider, so a per-row POST would put hundreds of tiny requests
// on the ingest surface for a signal that is only ever read in aggregate.
const CALLOUT_FEEDBACK_RECENT_MAX = 12;
const CALLOUT_VOTE_FLUSH_MS  = 30_000;
const CALLOUT_VOTE_MAX_BATCH = 25;
const _calloutFeedback = { dismissed: 0, expired: 0, uploaded: 0, recent: [] };
const _calloutVoteBuffer = [];
let _calloutVoteFlushTimer = null;
function _flushCalloutVotes() {
  if (_calloutVoteFlushTimer) { clearTimeout(_calloutVoteFlushTimer); _calloutVoteFlushTimer = null; }
  if (_calloutVoteBuffer.length === 0) return 0;
  const votes = _calloutVoteBuffer.splice(0, _calloutVoteBuffer.length);
  enqueueUpload('trigger_feedback', { agent_version: AGENT_VERSION, votes });
  _calloutFeedback.uploaded += votes.length;
  return votes.length;
}
