  if (group === 'charm' || group === 'mez' || group === 'lull') return BUILTIN_BAR_COLORS.mob;
  const good = _spellGood(spell);
  if (good === 1) return BUILTIN_BAR_COLORS.buff;
  const friendly = _knownPlayerName(String(targetName || '').trim().toLowerCase());
