  if (!/^\/api\/local\/parses(?:\/[0-9a-z-]+)?\/?(?:\?|$)/.test(req.url)) return false;
  const send = (out) => { res.writeHead(out.status, { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' }); res.end(JSON.stringify(out.body)); };
